import json
import re
import sys
import math
from functools import partial

def evaluate_expression(expr, variables):
    try:
        # Replace JSON literals with their numeric values
        for var_name in variables:
            if var_name in expr:
                expr = expr.replace(var_name, str(variables[var_name]))

        # Evaluate the arithmetic expression safely
        # Use a custom evaluator to handle only the allowed operations
        def safe_eval(expr):
            try:
                return eval(expr, {'__builtins__': None}, {})
            except:
                return float('nan')

        result = safe_eval(expr)
        return result
    except:
        return float('nan')

def process_template(template_path, values_path, output_path):
    with open(template_path, 'r', encoding='utf-8') as f:
        template = f.read()

    with open(values_path, 'r') as f:
        values = json.load(f)

    # Replace placeholders with evaluated expressions
    def replace_placeholder(match):
        expr = match.group(1).strip()
        value = evaluate_expression(expr, values)
        if math.isnan(value):
            return 'nan'
        elif value.is_integer():
            return str(int(value))
        else:
            return f"{value:.2f}"

    processed = re.sub(r'\{\{([^}]+)\}\}', replace_placeholder, template)

    with open(output_path, 'w', encoding='utf-8') as f:
        f.write(processed)

def compute_auth_tag(output_path, key_path):
    with open(key_path, 'r', encoding='utf-8') as f:
        key = f.read().strip()

    with open(output_path, 'rb') as f:
        data = f.read()

    # Compute HMAC-SHA256 hash of the output data with the key
    import hashlib
    hmac = hashlib.pbkdf2_hmac('sha256', data, key.encode('utf-8'), 100000)
    tag = hmac.hexdigest().lower()
    return tag

def main():
    if len(sys.argv) != 5:
        print("Usage: python render_report.py <template_path> <values_path> <key_path> <output_path>")
        sys.exit(1)

    template_path = sys.argv[1]
    values_path = sys.argv[2]
    key_path = sys.argv[3]
    output_path = sys.argv[4]

    process_template(template_path, values_path, output_path)
    auth_tag = compute_auth_tag(output_path, key_path)
    print(auth_tag)

if __name__ == "__main__":
    main()
